#include <stdio.h>
int main() {
    int a[10] = {10, 20, 30, 40, 50, 60, 70, 80, 90, 80};
    int sum = 0;
    for (int i = 0; i < 10; i++)
        sum += a[i];
    double avg1 = (double)sum / 10;
    double avg2 = sum / 10.0;
    printf("%.2f", avg1 + avg2);
    return 0;
}

